 * [12, 36, 54, 85, 98]
 * > pancakeSort([41, 42, 32, 12, 23])
 * [12, 23, 32, 41, 42]
 */
function pancakeSort(nums) {
  const len = nums.length;
  for (let i = len - 1; i > 0; i--) {
    let maxIndex = 0;
    for (let j = 1; j <= i; j++) {
      if (nums[j] > nums[maxIndex]) {
        maxIndex = j;
      }
    }
    if (maxIndex !== i) {
      // 翻转
      const temp = nums[i];
      nums[i] = nums[maxIndex];
      nums[maxIndex] = temp;
      // 翻转
      const temp2 = nums[i];
      nums[i] = nums[maxIndex];
      nums[maxIndex] = temp2;
    }
  }
  return nums;
}
