 * > getMaxgold([[10, 20], [30, 40]], 2, 2)
 * 70
 * > getMaxgold([[4, 9], [3, 7]], 2, 2)
 * 13
 */
function getMaxgold(gold, m, n) {
  const dp = new Array(m).fill(0).map(() => new Array(n).fill(0));
  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      if (i === 0 && j === 0) {
        dp[i][j] = gold[i][j];
      } else if (i === 0) {
        dp[i][j] = Math.max(dp[i][j - 1], gold[i][j]);
      } else if (j === 0) {
        dp[i][j] = Math.max(dp[i - 1][j], gold[i][j]);
      } else {
        dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1], gold[i][j]);
      }
    }
  }
  return dp[m - 1][n - 1];
}
